package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
//
// The original implementation scanned the input one byte at a time while
// juggling several intertwined pieces of state (header level, list depth,
// a "header already started" flag, ...), which made the control flow hard
// to follow. Every construct in this exercise is line-oriented, so the
// rewrite splits the input into lines and dispatches each line to a small
// helper. The only state kept across lines is whether a list or a
// paragraph is currently open.
//
// Emphasis is resolved up front, exactly as before: the first "__...__"
// pair becomes <strong>...</strong> and the first "_..._" pair becomes
// <em>...</em>. Bold is replaced before italic so that "__" is not
// mistaken for two single underscores.
func Render(markdown string) string {
	markdown = renderEmphasis(markdown)

	var html strings.Builder
	inList := false
	inParagraph := false

	closeParagraph := func() {
		if inParagraph {
			html.WriteString("</p>")
			inParagraph = false
		}
	}

	for _, line := range strings.Split(markdown, "\n") {
		if item, ok := listItem(line); ok {
			closeParagraph()
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString("<li>" + item)
			continue
		}
		if inList {
			html.WriteString("</li></ul>")
			inList = false
		}

		if level, ok := headerLevel(line); ok {
			closeParagraph()
			fmt.Fprintf(&html, "<h%d>%s</h%d>", level, line[level+1:], level)
			continue
		}

		if inParagraph {
			// Consecutive plain lines belong to the same paragraph,
			// so the line break is preserved.
			html.WriteString("\n")
		} else {
			html.WriteString("<p>")
			inParagraph = true
		}
		html.WriteString(line)
	}

	if inList {
		html.WriteString("</li></ul>")
	}
	closeParagraph()

	return html.String()
}

// renderEmphasis replaces the first "__...__" pair with
// <strong>...</strong> and the first "_..._" pair with <em>...</em>.
func renderEmphasis(markdown string) string {
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	markdown = strings.Replace(markdown, "_", "</em>", 1)
	return markdown
}

// headerLevel reports whether line is a header of the form "### text"
// with 1-6 leading hashes and returns the header level. Seven or more
// leading hashes is not a header; such lines are rendered as paragraphs.
func headerLevel(line string) (int, bool) {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level < 1 || level > 6 || level == len(line) || line[level] != ' ' {
		return 0, false
	}
	return level, true
}

// listItem reports whether line is a list item of the form "* text" and
// returns the item text without the leading "* ".
func listItem(line string) (string, bool) {
	if strings.HasPrefix(line, "* ") {
		return line[2:], true
	}
	return "", false
}

